DECLARE @minLoans int = 3;
EXEC sp_executesql
    N'SELECT ReaderId, ReaderName FROM (VALUES (1, N''Amy'', 5), (2, N''Ben'', 1)) AS r(ReaderId, ReaderName, LoanCount) WHERE LoanCount >= @minLoans',
    N'@minLoans int',
    @minLoans;
-- 結果：只有 Amy（LoanCount = 5 >= 3）；@stmt、@params 都要是 nvarchar（N'...'），不能是一般字串

DECLARE @readerName nvarchar(50);
EXEC sp_executesql
    N'SELECT @name = ReaderName FROM (VALUES (1, N''Amy''), (2, N''Ben'')) AS r(ReaderId, ReaderName) WHERE ReaderId = @id',
    N'@id int, @name nvarchar(50) OUTPUT',
    @id = 2,
    @name = @readerName OUTPUT;
SELECT @readerName;   -- 結果：Ben
SET @readerName = NULL;
EXEC sp_executesql
    N'SELECT @name = ReaderName FROM (VALUES (1, N''Amy''), (2, N''Ben'')) AS r(ReaderId, ReaderName) WHERE ReaderId = @id',
    N'@id int, @name nvarchar(50) OUTPUT',
    @id = 2,
    @name = @readerName;
SELECT @readerName;   -- 結果：NULL——呼叫端這次漏寫 OUTPUT，值就帶不回來

CREATE TABLE #t (ReaderId int, ReaderName nvarchar(50));
INSERT INTO #t
EXEC sp_executesql
    N'SELECT ReaderId, ReaderName FROM (VALUES (1, N''Amy''), (2, N''Ben'')) AS r(ReaderId, ReaderName) WHERE ReaderId > @minId',
    N'@minId int',
    @minId = 1;
SELECT * FROM #t;   -- 結果：只有一列 (2, 'Ben')
DROP TABLE #t;

CREATE TABLE #Cat_BookCopy (CopyNo int, Branch nvarchar(20));
