DECLARE @paramDef nvarchar(max) = N'@branch nvarchar(20)';
DECLARE @sql nvarchar(max) = N'SELECT COUNT(*) AS Cnt FROM ' + QUOTENAME(@tableName) + N' WHERE Branch = @branch';
EXEC sp_executesql @sql, @paramDef, @branch = N'Main';
