BEGIN TRANSACTION;
DECLARE @result int;
EXEC @result = sp_getapplock @Resource = N'Loan:CopyNo:1', @LockMode = N'Exclusive';
SELECT @result;   -- 結果：0（沒等待就直接取得鎖）
COMMIT TRANSACTION;   -- 交易結束，鎖自動釋放（@LockOwner 預設 'Transaction'）

DECLARE @result int;
EXEC @result = sp_getapplock @Resource = N'Loan:CopyNo:2', @LockMode = N'Exclusive', @LockOwner = N'Session';
SELECT @result;   -- 結果：0
EXEC sp_releaseapplock @Resource = N'Loan:CopyNo:2', @LockOwner = N'Session';
-- @LockOwner = 'Session' 要自己呼叫 sp_releaseapplock，不會隨交易結束自動放掉

DECLARE @result int;
EXEC @result = sp_getapplock @Resource = N'Loan:CopyNo:3', @LockMode = N'Exclusive';
-- 結果：呼叫失敗（8351：必須在交易內執行，@LockOwner 預設是 'Transaction'）
-- 要嘛先 BEGIN TRANSACTION，要嘛改 @LockOwner = 'Session'

DECLARE @result int;
EXEC sp_getapplock @Resource = N'Loan:CopyNo:4', @LockMode = N'Exclusive', @LockOwner = N'Session';
EXEC @result = sp_releaseapplock @Resource = N'Loan:CopyNo:4', @LockOwner = N'Session';
SELECT @result;   -- 結果：0（成功釋放）

BEGIN TRANSACTION;
EXEC sp_getapplock @Resource = N'Loan:CopyNo:5', @LockMode = N'Exclusive';
EXEC sp_releaseapplock @Resource = N'Loan:CopyNo:5';
-- 交易還沒 COMMIT，鎖已經提前手動釋放；@LockOwner 預設 'Transaction' 也能提前釋放，不必等交易結束
COMMIT TRANSACTION;

DECLARE @result int;
EXEC @result = sp_releaseapplock @Resource = N'Loan:CopyNo:999', @LockOwner = N'Session';
SELECT @result;
-- 結果：-999——這個工作階段沒持有這把鎖（名稱沒對到任何 sp_getapplock 呼叫），
-- @Resource／@LockOwner 要跟取得鎖時完全一致才放得掉

